// Mastodon mascot ROM — 128x128 pixels, 4-color palette.
// Single flat case on {y,x} with 2-bit palette index output.
// The 2-bit output (vs original 8-bit) keeps the mux tree 4x narrower.
//
// Effective VGA output: R[1:0]=pixel[7:6]  G[1:0]=pixel[5:4]  B[1:0]=pixel[3:2]
//
// Palette:
//   idx 0: 8'hFC  white   R=3 G=3 B=3  (default)
//   idx 1: 8'h00  black   R=0 G=0 B=0
//   idx 2: 8'hA8  grey    R=2 G=2 B=2
//   idx 3: 8'hE0  orange  R=3 G=2 B=0
// Color accuracy: 84.8% exact effective-VGA-color match vs the original.
`default_nettype none

module mastodon_rom_compress (
    input  wire [6:0] x,
    input  wire [6:0] y,
    output reg  [7:0] pixel
);

    reg [1:0] idx;

    always @(*) begin
        case ({y, x})
            14'd    8: idx = 2'd2;
            14'd    9: idx = 2'd2;
            14'd   10: idx = 2'd2;
            14'd   11: idx = 2'd2;
            14'd   12: idx = 2'd2;
            14'd   13: idx = 2'd2;
